type Manifest = {schema_version:'1.0';applicability:string;inputs:Record<string,any>;outputs:Record<string,any>;steps:{title:string;instruction:string}[];entrypoint:string|null;test_cases:{name:string;input:any;expected_output:any}[];dependencies:Binding[];tool_dependencies:ToolDependency[]};
