type SkillItem = {id:string;title:string;summary?:string;status:string;version:number;package_name?:string;package_revision?:number;digest?:string;updated_at?:string;managed?:boolean;last_test?:CheckReport|null};
type Detail = {entity:SkillItem;files:Record<string,string>;manifest:Manifest;package_name:string;package_revision:number;digest:string;validation:Validation;last_test?:CheckReport|null;history?:any[];read_only?:boolean;capabilities:{edit:boolean;submit:boolean;review:boolean;test:boolean;assist:boolean}};
