 const canBuild=!!session?.permissions.can_edit&&!session.workspace.readonly,editable=!!detail?.capabilities?.edit&&!detail?.read_only&&canBuild;
 const update=(patch:Partial<Draft>)=>setDraft(old=>old?{...old,...patch}:old);
 async function save(){if(!draft||!detail)return;setBusy('save');setError('');try{const m=manifestOf(draft);accept(await operation.run<Detail>(endpoint(id),{expected_version:detail.entity.version,title:draft.title,summary:draft.summary,files:draft.files,manifest:m,reason:saveReason.trim()||'完善技能内容'},'PUT'));toast('技能草稿已保存，后续校验与测试绑定本次内容。')}catch(e:any){if(e.name!=='AbortError')setError(errorText(e))}finally{setBusy('')}}
